"""Helpers for bulk feature definition generation."""

from __future__ import absolute_import


def gen_features(columns, classes=None, prefix="", suffix=""):
    """
    Generate DataFrameMapper feature definitions.
    """
    if classes is None:
        return [(column, None) for column in columns]

    feature_defs = []
    filtered_classes = [definition for definition in classes if definition is not None]

    for column in columns:
        arguments = {}
        if prefix:
            arguments["prefix"] = prefix
        if suffix:
            arguments["suffix"] = suffix

        if not filtered_classes:
            feature_defs.append((column, None, arguments))
            continue

        feature_transformers = []
        for definition in filtered_classes:
            if isinstance(definition, dict):
                params = definition.copy()
                klass = params.pop("class")
                feature_transformers.append(klass(**params))
            else:
                feature_transformers.append(definition())

        feature_defs.append((column, feature_transformers or None, arguments))

    return feature_defs


