"""Map pandas DataFrame columns to scikit-learn transformers."""

from __future__ import absolute_import

import contextlib
from datetime import datetime

import numpy as np
import pandas as pd
from scipy import sparse
from sklearn.base import BaseEstimator, TransformerMixin

from . import logger
from .cross_validation import DataWrapper
from .pipeline import TransformerPipeline, _call_fit, make_transformer_pipeline

string_types = text_type = str


def _handle_feature(fea):
    """
    Convert 1-dimensional arrays to 2-dimensional column vectors.
    """
    if sparse.issparse(fea):
        return fea

    if not hasattr(fea, "shape"):
        fea = np.asarray(fea)

    if len(fea.shape) == 1:
        fea = np.array([fea]).T

    return fea


def _build_transformer(transformers):
    if isinstance(transformers, (list, tuple)):
        transformers = make_transformer_pipeline(*transformers)
    return transformers


def _build_feature(columns, transformers, options={}, X=None):
    if X is None:
        return (columns, _build_transformer(transformers), options)
    return (
        columns(X) if callable(columns) else columns,
        _build_transformer(transformers),
        options,
    )


def _elapsed_secs(t1):
    return (datetime.now() - t1).total_seconds()


def _get_feature_names(estimator):
    """
    Attempt to extract feature names based on a given estimator.
    """
    if estimator is None:
        return None
    if hasattr(estimator, "classes_"):
        return estimator.classes_
    if hasattr(estimator, "get_feature_names_out"):
        try:
            return estimator.get_feature_names_out()
        except TypeError:
            pass
        except ValueError:
            pass
    if hasattr(estimator, "get_feature_names"):
        try:
            return estimator.get_feature_names()
        except TypeError:
            pass
        except ValueError:
            pass
    return None


@contextlib.contextmanager
def add_column_names_to_exception(column_names):
    """Prefix exceptions with the active column selector."""
    try:
        yield
    except Exception as ex:
        if ex.args:
            msg = u"{}: {}".format(column_names, ex.args[0])
        else:
            msg = text_type(column_names)
        ex.args = (msg,) + ex.args[1:]
        raise


def _is_column_list(columns):
    return isinstance(columns, (list, tuple, pd.Index, np.ndarray))


def _as_dense_array(value):
    if isinstance(value, (pd.Series, pd.DataFrame)):
        return value.values
    return np.asarray(value)


def _as_sparse_block(value):
    if sparse.issparse(value):
        return value
    return sparse.csr_matrix(_as_dense_array(value))


class DataFrameMapper(BaseEstimator, TransformerMixin):
    """
    Map pandas DataFrame column subsets to their own sklearn transformation.
    """

    def __init__(
        self,
        features,
        default=False,
        sparse=False,
        df_out=False,
        input_df=False,
        drop_cols=None,
    ):
        self.features = features
        self.default = default
        self.built_default = None
        self.sparse = sparse
        self.df_out = df_out
        self.input_df = input_df
        self.drop_cols = [] if drop_cols is None else drop_cols
        self.transformed_names_ = []
        if df_out and (sparse or default):
            raise ValueError("Can not use df_out with sparse or default")

    def _feature_definitions(self):
        if isinstance(self.features, list):
            return self.features
        return [self.features]

    def _built_feature_definitions(self):
        built = getattr(self, "built_features", None)
        if built is None:
            return self._feature_definitions()
        if isinstance(built, list):
            return built
        return [built]

    def _build(self, X=None):
        """
        Build attributes ``built_features`` and ``built_default``.
        """
        self.built_features = [
            _build_feature(*feature, X=X) for feature in self._feature_definitions()
        ]
        self.built_default = _build_transformer(self.default)

    @property
    def _selected_columns(self):
        """
        Return a set of selected columns in the feature list.
        """
        selected_columns = set()
        for feature in self._built_feature_definitions():
            columns = feature[0]
            if callable(columns):
                continue
            if isinstance(columns, string_types):
                selected_columns.add(columns)
            elif _is_column_list(columns):
                selected_columns.update(list(columns))
            else:
                selected_columns.add(columns)
        return selected_columns

    def _unselected_columns(self, X):
        """
        Return columns present in ``X`` and not explicitly selected in the mapper.
        """
        if not hasattr(X, "columns"):
            return []
        X_columns = list(X.columns)
        return [
            column
            for column in X_columns
            if column not in self._selected_columns and column not in self.drop_cols
        ]

    def __setstate__(self, state):
        super(DataFrameMapper, self).__setstate__(state)
        self.features = [_build_feature(*feat) for feat in state["features"]]
        self.sparse = state.get("sparse", False)
        self.default = state.get("default", False)
        self.df_out = state.get("df_out", False)
        self.input_df = state.get("input_df", False)
        self.drop_cols = state.get("drop_cols", [])
        self.built_features = state.get(
            "built_features", state.get("build_features", self.features)
        )
        self.built_default = state.get("built_default", self.default)
        self.transformed_names_ = state.get("transformed_names_", [])

    def __getstate__(self):
        state = super(DataFrameMapper, self).__getstate__()
        state["features"] = self.features
        state["sparse"] = self.sparse
        state["default"] = self.default
        state["df_out"] = self.df_out
        state["input_df"] = self.input_df
        state["drop_cols"] = self.drop_cols
        state["build_features"] = getattr(self, "built_features", None)
        state["built_features"] = getattr(self, "built_features", None)
        state["built_default"] = self.built_default
        state["transformed_names_"] = self.transformed_names_
        return state

    def _get_col_subset(self, X, cols, input_df=False):
        """
        Get a subset of columns from the given table ``X``.
        """
        if callable(cols):
            cols = cols(X)

        if isinstance(cols, string_types):
            return_vector = True
            cols = [cols]
        else:
            return_vector = False

        if isinstance(X, list):
            X = [x[cols] for x in X]
            X = pd.DataFrame(X)
        elif isinstance(X, DataWrapper):
            X = X.df

        if hasattr(X, "columns"):
            t = X[cols[0]] if return_vector else X[cols]
            return t if input_df else t.values

        array = np.asarray(X)
        if array.ndim == 1:
            t = array
        else:
            t = array[:, cols[0]] if return_vector else array[:, cols]
        return t if input_df else np.asarray(t)

    def fit(self, X, y=None):
        """
        Fit a transformation from the pipeline.
        """
        self._build(X=X)

        for columns, transformers, options in self._built_feature_definitions():
            t1 = datetime.now()
            input_df = options.get("input_df", self.input_df)

            if transformers is not None:
                with add_column_names_to_exception(columns):
                    Xt = self._get_col_subset(X, columns, input_df)
                    _call_fit(transformers.fit, Xt, y)
            logger.info("[FIT] %s: %s secs", columns, _elapsed_secs(t1))

        if self.built_default:
            unsel_cols = self._unselected_columns(X)
            if unsel_cols:
                with add_column_names_to_exception(unsel_cols):
                    Xt = self._get_col_subset(X, unsel_cols, self.input_df)
                    _call_fit(self.built_default.fit, Xt, y)

        return self

    def get_names(self, columns, transformer, x, alias=None, prefix="", suffix=""):
        """
        Return verbose names for the transformed columns.
        """
        if alias is not None:
            name = alias
        elif _is_column_list(columns):
            name = "_".join(map(str, columns))
        else:
            name = columns
        name = str(name)

        if sparse.issparse(x):
            num_cols = x.shape[1]
        elif hasattr(x, "shape") and len(x.shape) > 1:
            num_cols = x.shape[1]
        else:
            num_cols = 1

        output = []
        if num_cols > 1:
            if isinstance(transformer, TransformerPipeline):
                inverse_steps = transformer.steps[::-1]
                names = None
                for _, estimator in inverse_steps:
                    names = _get_feature_names(estimator)
                    if names is not None:
                        break
            else:
                names = _get_feature_names(transformer)

            if names is not None and len(names) == num_cols:
                output = ["%s_%s" % (name, item) for item in names]
            else:
                output = [name + "_" + str(item) for item in range(num_cols)]
        else:
            output = [name]

        if not prefix and not suffix:
            return output
        return ["{}{}{}".format(prefix, value, suffix) for value in output]

    def get_dtypes(self, extracted):
        dtypes_features = [self.get_dtype(extracted_feature) for extracted_feature in extracted]
        return [
            dtype
            for dtype_feature in dtypes_features
            for dtype in dtype_feature
        ]

    def get_dtype(self, extracted_feature):
        if sparse.issparse(extracted_feature) or isinstance(extracted_feature, np.ndarray):
            return [extracted_feature.dtype] * extracted_feature.shape[1]
        if isinstance(extracted_feature, pd.DataFrame):
            return list(extracted_feature.dtypes)
        if isinstance(extracted_feature, pd.Series):
            return [extracted_feature.dtype]
        raise TypeError(type(extracted_feature))

    def _stack(self, extracted, X):
        if not extracted:
            if self.df_out:
                index = X.index if hasattr(X, "index") else None
                return pd.DataFrame(index=index)
            if self.sparse:
                return sparse.csr_matrix((len(X), 0))
            return np.empty((len(X), 0))

        if any(sparse.issparse(feature) for feature in extracted):
            stacked = sparse.hstack(
                [_as_sparse_block(feature) for feature in extracted]
            ).tocsr()
            if not self.sparse:
                stacked = stacked.toarray()
        else:
            stacked = np.hstack([_as_dense_array(feature) for feature in extracted])

        if not self.df_out:
            return stacked

        no_rows_dropped = len(X) == len(stacked)
        index = X.index if hasattr(X, "index") and no_rows_dropped else None
        dtypes = self.get_dtypes(extracted)
        df_out = pd.DataFrame(
            stacked,
            columns=self.transformed_names_,
            index=index,
        )
        for column, dtype in zip(self.transformed_names_, dtypes):
            df_out[column] = df_out[column].astype(dtype)
        return df_out

    def _transform(self, X, y=None, do_fit=False):
        """
        Transform the given data with possibility to fit in advance.
        """
        if do_fit:
            self._build(X=X)

        extracted = []
        transformed_names_ = []

        for columns, transformers, options in self._built_feature_definitions():
            input_df = options.get("input_df", self.input_df)
            Xt = self._get_col_subset(X, columns, input_df)

            if transformers is not None:
                with add_column_names_to_exception(columns):
                    if do_fit and hasattr(transformers, "fit_transform"):
                        t1 = datetime.now()
                        Xt = _call_fit(transformers.fit_transform, Xt, y)
                        logger.info(
                            "[FIT_TRANSFORM] %s: %s secs",
                            columns,
                            _elapsed_secs(t1),
                        )
                    else:
                        if do_fit:
                            t1 = datetime.now()
                            _call_fit(transformers.fit, Xt, y)
                            logger.info("[FIT] %s: %s secs", columns, _elapsed_secs(t1))

                        t1 = datetime.now()
                        Xt = transformers.transform(Xt)
                        logger.info(
                            "[TRANSFORM] %s: %s secs",
                            columns,
                            _elapsed_secs(t1),
                        )

            extracted.append(_handle_feature(Xt))
            transformed_names_ += self.get_names(
                columns,
                transformers,
                Xt,
                options.get("alias"),
                options.get("prefix", ""),
                options.get("suffix", ""),
            )

        if self.built_default is not False:
            unsel_cols = self._unselected_columns(X)
            if unsel_cols:
                Xt = self._get_col_subset(X, unsel_cols, self.input_df)
                if self.built_default is not None:
                    with add_column_names_to_exception(unsel_cols):
                        if do_fit and hasattr(self.built_default, "fit_transform"):
                            Xt = _call_fit(self.built_default.fit_transform, Xt, y)
                        else:
                            if do_fit:
                                _call_fit(self.built_default.fit, Xt, y)
                            Xt = self.built_default.transform(Xt)
                    transformed_names_ += self.get_names(
                        unsel_cols, self.built_default, Xt
                    )
                else:
                    transformed_names_ += unsel_cols

                extracted.append(_handle_feature(Xt))

        self.transformed_names_ = transformed_names_
        return self._stack(extracted, X)

    def transform(self, X):
        """
        Transform the given data. Assumes that fit has already been called.
        """
        return self._transform(X)

    def fit_transform(self, X, y=None):
        """
        Fit a transformation from the pipeline and directly apply it.
        """
        return self._transform(X, y, True)


