"""Pipeline helpers compatible with sklearn-pandas."""

from __future__ import absolute_import

from sklearn.pipeline import Pipeline, _name_estimators

try:
    from sklearn.utils import tosequence
except ImportError:  # pragma: no cover
    def tosequence(value):
        return list(value)


def _call_fit(fit_method, X, y=None, **kwargs):
    """
    Call ``fit`` or ``fit_transform`` with or without ``y``.

    This intentionally mirrors sklearn-pandas' permissive legacy behavior.
    """
    try:
        return fit_method(X, y, **kwargs)
    except TypeError:
        return fit_method(X, **kwargs)


class TransformerPipeline(Pipeline):
    """
    Pipeline made exclusively of transformers.

    Each step must expose ``fit`` or ``fit_transform`` and ``transform``.
    """

    def __init__(self, steps):
        names, estimators = zip(*steps)
        if len(dict(steps)) != len(steps):
            raise ValueError(
                "Provided step names are not unique: %s" % (names,)
            )

        estimator = estimators[-1]
        for transform in estimators:
            if (
                not (hasattr(transform, "fit") or hasattr(transform, "fit_transform"))
                or not hasattr(transform, "transform")
            ):
                raise TypeError(
                    "All steps of the chain should be transforms and implement fit "
                    "and transform '%s' (type %s) doesn't)"
                    % (transform, type(transform))
                )

        if not hasattr(estimator, "fit"):
            raise TypeError(
                "Last step of chain should implement fit '%s' (type %s) doesn't)"
                % (estimator, type(estimator))
            )

        super(TransformerPipeline, self).__init__(steps=tosequence(steps))

    def _pre_transform(self, X, y=None, **fit_params):
        """Fit and transform all steps except the last one."""
        fit_params_steps = dict((step, {}) for step, _ in self.steps)
        for pname, pval in fit_params.items():
            step, param = pname.split("__", 1)
            fit_params_steps[step][param] = pval

        Xt = X
        for name, transform in self.steps[:-1]:
            if hasattr(transform, "fit_transform"):
                Xt = _call_fit(
                    transform.fit_transform, Xt, y, **fit_params_steps[name]
                )
            else:
                Xt = _call_fit(transform.fit, Xt, y, **fit_params_steps[name]).transform(
                    Xt
                )
        return Xt, fit_params_steps[self.steps[-1][0]]

    def fit(self, X, y=None, **fit_params):
        """Fit the pipeline."""
        Xt, fit_params_last = self._pre_transform(X, y, **fit_params)
        _call_fit(self.steps[-1][-1].fit, Xt, y, **fit_params_last)
        return self

    def fit_transform(self, X, y=None, **fit_params):
        """Fit the pipeline and transform with the last step."""
        Xt, fit_params_last = self._pre_transform(X, y, **fit_params)
        if hasattr(self.steps[-1][-1], "fit_transform"):
            return _call_fit(
                self.steps[-1][-1].fit_transform, Xt, y, **fit_params_last
            )
        return _call_fit(self.steps[-1][-1].fit, Xt, y, **fit_params_last).transform(
            Xt
        )


def make_transformer_pipeline(*steps):
    """Construct a :class:`TransformerPipeline` from the given transformers."""
    return TransformerPipeline(_name_estimators(steps))


__all__ = ["TransformerPipeline", "_call_fit", "make_transformer_pipeline"]

