"""Utility transformers."""

from __future__ import absolute_import

import warnings

import numpy as np
import pandas as pd
from sklearn.base import BaseEstimator, TransformerMixin


def _get_mask(X, value):
    """Compute the boolean mask ``X == value`` with null support."""
    if (
        value == "NaN"
        or value is None
        or (isinstance(value, float) and np.isnan(value))
    ):
        return pd.isnull(X)
    return X == value


class NumericalTransformer(BaseEstimator, TransformerMixin):
    """
    Provides commonly used numerical transformers.
    """

    SUPPORTED_FUNCTIONS = ["log", "log1p"]

    def __init__(self, func):
        warnings.warn(
            """
            NumericalTransformer will be deprecated in 3.0 version.
            Please use Sklearn.base.TransformerMixin to write
            customer transformers
            """,
            DeprecationWarning,
            stacklevel=2,
        )

        assert func in self.SUPPORTED_FUNCTIONS, (
            "Only following func are supported: %s" % (self.SUPPORTED_FUNCTIONS,)
        )
        super(NumericalTransformer, self).__init__()
        self.func = func
        self.__func = func

    def fit(self, X, y=None):
        return self

    def transform(self, X, y=None):
        values = np.asarray(X)
        try:
            numeric_values = values.astype(float)
        except (TypeError, ValueError):
            raise ValueError(
                "NumericalTransformer('%s') requires numeric input." % self.func
            )

        finite_mask = np.isfinite(numeric_values)
        if self.func == "log":
            if np.any(numeric_values[finite_mask] <= 0):
                raise ValueError(
                    "NumericalTransformer('log') requires all finite values to be > 0."
                )
            return np.log(X)

        if self.func == "log1p":
            if np.any(numeric_values[finite_mask] <= -1):
                raise ValueError(
                    "NumericalTransformer('log1p') requires all finite values to be > -1."
                )
            return np.log1p(X)

        raise ValueError("Invalid function name: %s" % self.__func)


__all__ = ["NumericalTransformer", "_get_mask"]

